Rechnung r = new Rechnung(42, 99);
Zeugnis z = new Zeugnis("Lena", 1);

r.Drucken();
z.Drucken();
// Ausgabe:
// Rechnung Nr. 42 über 99 Euro
// Zeugnis von Lena, Durchschnitt: 1

interface IDruckbar
{
    void Drucken();
}

class Rechnung : IDruckbar
{
    private int nummer;
    private int betrag;

    public Rechnung(int nummer, int betrag)
    {
        this.nummer = nummer;
        this.betrag = betrag;
    }

    public void Drucken()
    {
        Console.WriteLine($"Rechnung Nr. {nummer} über {betrag} Euro");
    }
}

class Zeugnis : IDruckbar
{
    private string name;
    private int schnitt;

    public Zeugnis(string name, int schnitt)
    {
        this.name = name;
        this.schnitt = schnitt;
    }

    public void Drucken()
    {
        Console.WriteLine($"Zeugnis von {name}, Durchschnitt: {schnitt}");
    }
}

IDruckbar[] stapel = { new Foto("Urlaub.jpg"), new Brief("Oma"), new Foto("Klasse.png") };

foreach (IDruckbar d in stapel)
{
    d.Drucken();
}
Console.WriteLine($"{stapel.Length} Seiten gedruckt.");
// Ausgabe:
// Foto: Urlaub.jpg
// Brief an Oma
// Foto: Klasse.png
// 3 Seiten gedruckt.

interface IDruckbar
{
    void Drucken();
}

class Foto : IDruckbar
{
    private string datei;
    public Foto(string datei) { this.datei = datei; }
    public void Drucken() => Console.WriteLine($"Foto: {datei}");
}

class Brief : IDruckbar
{
    private string empfaenger;
    public Brief(string empfaenger) { this.empfaenger = empfaenger; }
    public void Drucken() => Console.WriteLine($"Brief an {empfaenger}");
}

Ente donald = new Ente("Donald");
donald.Schwimmen();
donald.Fliegen();
Console.WriteLine($"Flughöhe: {donald.MaxHoehe} m");
// Ausgabe:
// Donald paddelt.
// Donald flattert los.
// Flughöhe: 300 m

interface ISchwimmer
{
    void Schwimmen();
}

interface IFlieger
{
    int MaxHoehe { get; }
    void Fliegen();
}

class Tier
{
    public string Name { get; }
    public Tier(string name) { Name = name; }
}

// zuerst die Basisklasse, dann die Interfaces
class Ente : Tier, ISchwimmer, IFlieger
{
    public int MaxHoehe { get; } = 300;

    public Ente(string name) : base(name) { }

    public void Schwimmen() => Console.WriteLine($"{Name} paddelt.");
    public void Fliegen() => Console.WriteLine($"{Name} flattert los.");
}

